use super::*;
use crate::pet_runtime::{restored_future::{self,Review as FutureReview},store::Store,model::{Spec,Context,Action,PreparationMode,CommitStatus,Error}};
fn store(f:&Fixture)->Store{Store::existing_verified(&f.path.join("goals"),&root(f)).unwrap().unwrap()}
fn future(f:&Fixture,old:&Record,request:&str)->FutureReview{
 let spec=Spec{restored_from:None,request_id:restored_future::request_id(&old.spec.owner.pet_id,&old.id,&old.revision,request).unwrap(),owner:old.spec.owner.clone(),context:Context::Unbound,intent:"Future responsibility explicitly reviewed".into(),criteria:vec!["Future criterion with independent verification".into()]};
 FutureReview::prepare(&store(f),&root(f),&old.id,&old.spec.owner.pet_id,&old.revision,spec,request.into(),100_010).unwrap()
}
fn source()->(Fixture,Fixture,Record){let result=copy_fixture();install(&result.1);result}
fn create(f:&Fixture,old:&Record,request:&str)->Record{let mut review=future(f,old,request);assert!(review.decide(&store(f),true,true,100_011).unwrap());store(f).create_restored_future(&review.approved().unwrap(),100_012).unwrap().record}
pub(in crate::pet_runtime)fn prepared_fixture()->(Fixture,Fixture,Record,FutureReview){let(from,to,old)=source();let review=future(&to,&old,"native-window-scope");(from,to,old,review)}
fn bind(f:&Fixture,goal:&Record)->Record{let main=crate::chat::Chat::persistent(f.path.join("fresh-main.json"));let(binding,hold)=crate::pet_runtime::context::prepare(&f.path.join("future-contexts"),goal,&main,PreparationMode::Dedicated,"future-own-context").unwrap();drop(hold);store(f).mutate(&goal.id,&goal.spec.owner.pet_id,&goal.revision,"future-own-context".into(),Action::BindContext{binding},100_020).unwrap().record}

#[test]fn completed_restored_source_is_read_only_data_and_can_create_a_new_independent_draft(){
 let f=Fixture::new();f.store();let raw=include_bytes!("fixtures/restored-completed-synthetic.json");let old:Record=serde_json::from_slice(raw).unwrap();old.validate().unwrap();assert_eq!(old.state,crate::pet_runtime::model::State::Completed);let file=f.path.join("goals").join(format!("{}.json",old.id));fs::write(&file,raw).unwrap();fs::set_permissions(&file,fs::Permissions::from_mode(0o600)).unwrap();Authority::ensure(&root(&f)).unwrap();install(&f);let before=bytes(&root(&f));let now=old.updated_at+10;
 let store=store(&f);let read=store.read(&old.id,&old.spec.owner.pet_id).unwrap();assert_eq!(model::fingerprint(&read).unwrap(),model::fingerprint(&old).unwrap());let listing=store.list(None).unwrap();assert!(listing.complete);assert_eq!(listing.goals.len(),1);assert!(listing.goals[0].historical_source);assert!(store.read_control(&old.id,&old.spec.owner.pet_id).is_err());assert!(store.mutate(&old.id,&old.spec.owner.pet_id,&old.revision,"must-not-control-history".into(),Action::Pause,now).is_err());assert_eq!(fs::read(&file).unwrap(),raw);
 let request="future-of-completed-snapshot";let spec=Spec{restored_from:None,request_id:restored_future::request_id(&old.spec.owner.pet_id,&old.id,&old.revision,request).unwrap(),owner:old.spec.owner.clone(),context:Context::Unbound,intent:"Independently reviewed future work".into(),criteria:vec!["Independently verified future criterion".into()]};let mut review=FutureReview::prepare(&store,&root(&f),&old.id,&old.spec.owner.pet_id,&old.revision,spec,request.into(),now).unwrap();assert!(review.decide(&store,true,true,now+1).unwrap());let new=store.create_restored_future(&review.approved().unwrap(),now+2).unwrap().record;assert_ne!(new.id,old.id);assert_eq!(new.schema_version,13);assert!(store.read_control(&new.id,&new.spec.owner.pet_id).is_ok());assert!(new.admissions.is_empty()&&new.execution_context.is_none());assert_eq!(bytes(&root(&f)),before);assert_eq!(fs::read(&file).unwrap(),raw);let listing=store.list(None).unwrap();assert_eq!(listing.goals.iter().filter(|g|g.historical_source).count(),1);
}

#[test]fn exact_data_review_creates_only_new_schema13_draft_with_no_old_authority_balance_or_context(){
 let(_from,to,old)=source();let authority_before=bytes(&root(&to));let old_bytes=fs::read(to.path.join("goals").join(format!("{}.json",old.id))).unwrap();let mut review=future(&to,&old,"new-future-data");let p=review.proposal();assert!(!p.execution_authority_granted&&!p.context_copied&&!p.historical_budget_reused&&!p.owner_absence_proven&&p.post_snapshot_state_unknown);assert_eq!(bytes(&root(&to)),authority_before);assert!(review.approved().is_err());assert!(review.decide(&store(&to),true,true,100_011).unwrap());
 let approved=review.approved().unwrap();let receipt=store(&to).create_restored_future(&approved,100_012).unwrap();assert_eq!(receipt.status,CommitStatus::Durable);let goal=receipt.record;assert_ne!(goal.id,old.id);assert_eq!(goal.schema_version,13);assert!(goal.admissions.is_empty()&&goal.execution_context.is_none()&&goal.tasks.is_empty()&&goal.plans.is_empty());assert!(matches!(goal.spec.context,Context::Unbound));let origin=goal.spec.restored_from.as_ref().unwrap();assert_eq!(origin.body.source.goal_hash,model::fingerprint(&old).unwrap());assert_eq!(origin.body.client_request_id,"new-future-data");assert!(!origin.body.execution_authority_granted&&!origin.body.accounting_known&&origin.body.unknown_state_accepted);let a=Authority::existing(&root(&to)).unwrap();a.verify_restored_origin(&goal).unwrap();assert_eq!(a.verify_queued(&old,100_030).err(),Some(Failure::RecoveryRequired));assert_eq!(bytes(&root(&to)),authority_before);assert_eq!(fs::read(to.path.join("goals").join(format!("{}.json",old.id))).unwrap(),old_bytes);assert_eq!(store(&to).read(&goal.id,&goal.spec.owner.pet_id).unwrap().schema_version,13);
}

#[test]fn missing_uncertainty_choice_decline_expiry_or_changed_source_never_creates_a_future_goal(){
 for variant in ["ack","decline","expired","goal","grant","marker","key"]{
  let(_from,to,old)=source();let mut review=future(&to,&old,variant);let id=review.proposal().target_goal_id;
  match variant{"goal"=>fs::write(to.path.join("goals").join(format!("{}.json",old.id)),b"changed source goal").unwrap(),"grant"=>fs::write(root(&to).join(format!("{}.json",old.admissions[0].spec.decision_id)),b"changed source accounting").unwrap(),"marker"=>fs::write(root(&to).join(INDEX),b"changed native source").unwrap(),"key"=>fs::write(root(&to).join(KEY),b"changed signer").unwrap(),_=>{}}
  let before=bytes(&root(&to));let decision=review.decide(&store(&to),variant!="decline",variant!="ack",if variant=="expired"{220_010}else{100_011});if variant=="decline"{assert!(!decision.unwrap());}else{assert!(decision.is_err(),"{variant}");}assert!(review.approved().is_err());assert!(!to.path.join("goals").join(format!("{id}.json")).exists());assert_eq!(bytes(&root(&to)),before);
 }
}

#[test]fn original_schema_and_codec_preserve_plain_spec_while_older_spec_codec_refuses_origin(){
 #[derive(serde::Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]#[allow(dead_code)]struct OldSpec{request_id:String,owner:crate::pet_runtime::model::Owner,context:Context,intent:String,criteria:Vec<String>}
 let(_from,to,old)=source();let before=serde_json::to_vec(&old.spec).unwrap();let plain:OldSpec=serde_json::from_slice(&before).unwrap();assert_eq!(plain.intent,old.spec.intent);assert!(serde_json::to_value(&old.spec).unwrap().get("restoredFrom").is_none());let goal=create(&to,&old,"old-codec-boundary");assert!(serde_json::from_slice::<OldSpec>(&serde_json::to_vec(&goal.spec).unwrap()).is_err());let mut downgraded=goal.clone();downgraded.schema_version=12;assert!(downgraded.validate().is_err());assert_eq!(serde_json::to_vec(&old.spec).unwrap(),before);
}

#[test]fn generic_creation_namespace_body_tag_owner_or_argument_tamper_never_forges_native_origin(){
 for variant in ["generic","namespace","tag","intent","owner","purpose","grantFlag","target"]{
  let(_from,to,old)=source();let mut goal=create(&to,&old,variant);let a=Authority::existing(&root(&to)).unwrap();
  if variant=="generic"{assert!(store(&to).create(goal.spec.clone(),100_030).is_err());continue;}
  if variant=="namespace"{let mut spec=goal.spec.clone();spec.restored_from=None;spec.request_id="rf-unowned-new-reservation".into();assert!(store(&to).create(spec,100_030).is_err());continue;}
  match variant{"tag"=>goal.spec.restored_from.as_mut().unwrap().tag="0".repeat(64),"intent"=>{goal.spec.intent+=" forged";let hash=restored_future::base_hash(&goal.spec).unwrap();goal.spec.restored_from.as_mut().unwrap().body.base_spec_hash=hash;},"owner"=>goal.spec.owner.pet_id="ai_ollama".into(),"purpose"=>goal.spec.restored_from.as_mut().unwrap().body.purpose="executeWithOldAuthority".into(),"grantFlag"=>goal.spec.restored_from.as_mut().unwrap().body.execution_authority_granted=true,_=>goal.spec.restored_from.as_mut().unwrap().body.target_goal_id=old.id.clone()};goal.events[0].fingerprint=model::fingerprint(&goal.spec).unwrap();assert!(a.verify_restored_origin(&goal).is_err(),"{variant}");let path=to.path.join("goals").join(format!("{}.json",goal.id));fs::write(&path,serde_json::to_vec(&goal).unwrap()).unwrap();assert!(store(&to).read(&goal.id,&old.spec.owner.pet_id).is_err());
 }
}

#[test]fn each_creation_publish_cut_reuses_original_signature_and_ack_does_not_renew_authority(){
 for cut in [crate::pet_runtime::store::Fault::BeforePublish,crate::pet_runtime::store::Fault::AfterPublish]{
  let(_from,to,old)=source();let mut review=future(&to,&old,"creation-cut");review.decide(&store(&to),true,true,100_011).unwrap();let original=review.approved().unwrap().spec.clone();let mut damaged=store(&to);damaged.fault=cut;let result=damaged.create_restored_future(&review.approved().unwrap(),100_012);
  if matches!(cut,crate::pet_runtime::store::Fault::BeforePublish){assert!(result.is_err());}else{assert_eq!(result.unwrap().status,CommitStatus::Uncertain);assert!(review.decide(&store(&to),false,false,100_013).is_err());}
  let receipt=store(&to).create_restored_future(&review.approved().unwrap(),100_014).unwrap();assert_eq!(receipt.record.spec,original);let key=bytes(&root(&to));fs::remove_file(to.path.join("goals").join(format!("{}.json",old.id))).unwrap();let ack=store(&to).create_restored_future(&review.approved().unwrap(),300_000).unwrap();assert_eq!(ack.record.spec,original);assert_eq!(ack.status,CommitStatus::Unchanged);assert_eq!(bytes(&root(&to)),key);let origin=ack.record.spec.restored_from.as_ref().unwrap();assert_eq!(origin.body.approved_at,100_011);
 }
}

#[test]fn expiry_during_staging_stops_before_rename_and_after_publish_is_only_uncertain(){
 for expired_call in [3,4,5]{let(_from,to,old)=source();let mut review=future(&to,&old,"clock-cut");review.decide(&store(&to),true,true,100_011).unwrap();let id=review.proposal().target_goal_id;let count=Cell::new(0);let result=store(&to).create_restored_future_clock(&review.approved().unwrap(),||{count.set(count.get()+1);if count.get()>=expired_call{220_010}else{100_012}});
  if expired_call<5{assert!(result.is_err());assert!(!to.path.join("goals").join(format!("{id}.json")).exists());}else{assert_eq!(result.unwrap().status,CommitStatus::Uncertain);assert_eq!(store(&to).create_restored_future(&review.approved().unwrap(),300_000).unwrap().status,CommitStatus::Unchanged);}
 }
}

#[test]fn fresh_context_and_admission_use_same_runtime_and_bind_origin_to_the_signed_intent(){
 let(_from,to,old)=source();let goal=create(&to,&old,"future-runtime");let goal=bind(&to,&goal);assert_eq!(goal.schema_version,13);let a=Authority::existing(&root(&to)).unwrap();let approval=crate::pet_runtime::admission::Review::prepare(&goal,evidence(&goal,100_022),crate::pet_runtime::admission_tests::budget(),"future-own-budget".into(),nonce().unwrap(),100_022).unwrap().approve(&goal,evidence(&goal,100_023),100_023).unwrap();let certificate=a.certify(&approval,&goal,100_030).unwrap();let queued=store(&to).enqueue_certified(&certificate,100_031).unwrap().record;assert_eq!(queued.schema_version,13);assert_eq!(queued.admissions[0].spec.intent_hash,model::fingerprint(&queued.spec).unwrap());assert_ne!(queued.admissions[0].spec.decision_id,old.admissions[0].spec.decision_id);a.verify_queued(&queued,100_032).unwrap();assert_eq!(a.verify_queued(&old,100_032).err(),Some(Failure::RecoveryRequired));let h=a.history(&queued,100_032).unwrap();assert_eq!(h.schema_version,1);assert!(h.restored_source.is_none());
 let mut wrong=queued.clone();wrong.spec.restored_from.as_mut().unwrap().tag="0".repeat(64);assert!(wrong.validate().is_err());let mut data_proof=queued.admissions[0].proof.as_ref().unwrap().clone();data_proof.tag=queued.spec.restored_from.as_ref().unwrap().tag.clone();assert!(a.load(&queued.admissions[0].spec,&data_proof).is_err());
}

#[test]fn existing_creation_can_be_acknowledged_after_source_removal_without_redirect_or_argument_reuse(){
 let(_from,to,old)=source();let goal=create(&to,&old,"stable-ack");let current=bind(&to,&goal);fs::remove_file(to.path.join("goals").join(format!("{}.json",old.id))).unwrap();let ack=store(&to).existing_restored_future(&old.spec.owner.pet_id,&old.id,&old.revision,"stable-ack",&goal.spec.intent,&goal.spec.criteria).unwrap().unwrap();assert_eq!(ack.record.revision,current.revision);assert_eq!(ack.record.spec,goal.spec);assert!(store(&to).existing_restored_future(&old.spec.owner.pet_id,&old.id,&old.revision,"stable-ack","different future arguments",&goal.spec.criteria).is_err());assert!(store(&to).existing_restored_future(&old.spec.owner.pet_id,&old.id,&"b".repeat(32),"stable-ack",&goal.spec.intent,&goal.spec.criteria).unwrap().is_none());
}
#[test]fn changed_source_after_approval_and_a_foreign_profile_never_receive_the_new_record(){
 for variant in ["source","foreign"]{let(_from,to,old)=source();let mut review=future(&to,&old,variant);review.decide(&store(&to),true,true,100_011).unwrap();let target=review.proposal().target_goal_id;
  if variant=="source"{fs::write(root(&to).join(format!("{}.json",old.admissions[0].spec.decision_id)),b"revoked source accounting during wait").unwrap();assert!(store(&to).create_restored_future(&review.approved().unwrap(),100_012).is_err());}else{let other=Fixture::new();other.goal("codex");Authority::ensure(&root(&other)).unwrap();assert!(store(&other).create_restored_future(&review.approved().unwrap(),100_012).is_err());assert!(!other.path.join("goals").join(format!("{target}.json")).exists());}assert!(!to.path.join("goals").join(format!("{target}.json")).exists());
 }
}

#[test]fn an_existing_execution_grant_prevents_recreation_of_a_removed_future_record(){
 let(_from,to,old)=source();let goal=create(&to,&old,"known-target-grant");let goal=bind(&to,&goal);let a=Authority::existing(&root(&to)).unwrap();let approval=crate::pet_runtime::admission::Review::prepare(&goal,evidence(&goal,100_022),crate::pet_runtime::admission_tests::budget(),"target-live-grant".into(),nonce().unwrap(),100_022).unwrap().approve(&goal,evidence(&goal,100_023),100_023).unwrap();a.certify(&approval,&goal,100_030).unwrap();fs::remove_file(to.path.join("goals").join(format!("{}.json",goal.id))).unwrap();let mut base=goal.spec.clone();base.restored_from=None;assert!(FutureReview::prepare(&store(&to),&root(&to),&old.id,&old.spec.owner.pet_id,&old.revision,base,"known-target-grant".into(),100_040).is_err());assert!(!to.path.join("goals").join(format!("{}.json",goal.id)).exists());
}

#[test]fn a_future13_goal_becomes_historical_in_the_next_epoch_without_reactivating_its_certificate(){
 let(_from,to,old)=source();let goal=create(&to,&old,"first-future13");let goal=bind(&to,&goal);let a=Authority::existing(&root(&to)).unwrap();let approval=crate::pet_runtime::admission::Review::prepare(&goal,evidence(&goal,100_022),crate::pet_runtime::admission_tests::budget(),"first-future-own-budget".into(),nonce().unwrap(),100_022).unwrap().approve(&goal,evidence(&goal,100_023),100_023).unwrap();let certificate=a.certify(&approval,&goal,100_030).unwrap();let goal=store(&to).enqueue_certified(&certificate,100_031).unwrap().record;let raw=fs::read(to.path.join("goals").join(format!("{}.json",goal.id))).unwrap();drop(a);
 let next=crate::pet_runtime::restoration::EpochReview::capture(&root(&to),&to.path.join("goals"),&"b".repeat(64),||Ok(())).unwrap();let hash=next.fingerprint().unwrap();next.apply(&hash,||Ok(())).unwrap();let a=Authority::existing(&root(&to)).unwrap();assert_eq!(a.verify_queued(&goal,100_040).err(),Some(Failure::RecoveryRequired));let view=a.history(&goal,100_040).unwrap();assert_eq!(view.schema_version,2);assert!(!view.accounting_complete&&!view.continuation_available);assert!(store(&to).read(&goal.id,&goal.spec.owner.pet_id).is_ok());assert!(store(&to).read_control(&goal.id,&goal.spec.owner.pet_id).is_err());
 let request="future13-after-another-epoch";let spec=Spec{restored_from:None,request_id:restored_future::request_id(&goal.spec.owner.pet_id,&goal.id,&goal.revision,request).unwrap(),owner:goal.spec.owner.clone(),context:Context::Unbound,intent:"Separate future after another restoration".into(),criteria:vec!["Verify independently".into()]};let mut review=FutureReview::prepare(&store(&to),&root(&to),&goal.id,&goal.spec.owner.pet_id,&goal.revision,spec,request.into(),100_041).unwrap();review.decide(&store(&to),true,true,100_042).unwrap();let future=store(&to).create_restored_future(&review.approved().unwrap(),100_043).unwrap().record;assert_eq!(future.schema_version,13);assert_ne!(future.id,goal.id);assert!(future.admissions.is_empty()&&future.execution_context.is_none());assert_eq!(future.spec.restored_from.as_ref().unwrap().body.source.goal_id,goal.id);assert!(store(&to).read_control(&future.id,&future.spec.owner.pet_id).is_ok());assert_eq!(fs::read(to.path.join("goals").join(format!("{}.json",goal.id))).unwrap(),raw);
}
